    group.add(base);
    colliders.push(new THREE.Box3().setFromObject(base));

    const positions = [
      { dx: -5, dz: -5 }, { dx: 5, dz: -5 }, { dx: -5, dz: 5 }, { dx: 5, dz: 5 },
      { dx: 0, dz: -7 }, { dx: 0, dz: 7 }, { dx: -7, dz: 0 }, { dx: 7, dz: 0 },
