      new THREE.CylinderGeometry(3, 3, 0.2, 8),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(teamColor === 'CT' ? PALETTE.ct : PALETTE.t), transparent: true, opacity: 0.3, side: THREE.DoubleSide })
    );
    marker.position.set(x, 0.1, z);
