    bots,
    botMeshes,
    update: (dt, gameState) => {
      bots.forEach(bot => updateBot(bot, dt, gameState));
    },
    respawnBot,
    getAlive: (team) => bots.filter(b => b.alive && b.team === team),
    getAll: () => bots,
